diff --git a/mail/base/content/widgets/glodaFacet.js b/mail/base/content/widgets/glodaFacet.js
index 44f688e1c45..42f7309b363 100644
--- a/mail/base/content/widgets/glodaFacet.js
+++ b/mail/base/content/widgets/glodaFacet.js
@@ -167,7 +167,7 @@
       // set the count so CSS selectors can know what the results look like
       this.setAttribute("state", totalCount <= 0 ? "empty" : "some");

-      document.l10n.setAttributes(this.countNode, "items-m-of-n", {
+      document.l10n.setAttributes(this.countNode, "item-count-m-of-n", {
         m: displayCount,
         n: totalCount,
       });
diff --git a/mail/locales/en-US/messenger/glodaFacetView.ftl b/mail/locales/en-US/messenger/glodaFacetView.ftl
index 451d528f534..11bd9ac4cf4 100644
--- a/mail/locales/en-US/messenger/glodaFacetView.ftl
+++ b/mail/locales/en-US/messenger/glodaFacetView.ftl
@@ -5,19 +5,7 @@
 # Variables:
 #   $m - the number M in "M of N" items
 #   $n - the number N in "M of N" items
-items-m-of-n =
-    { $m ->
-        [one]
-            { $m ->
-                [one] { $m } of { $n }
-               *[other] { $m } of { $n }
-            }
-       *[other]
-            { $m ->
-                [one] { $m } of { $n }
-               *[other] { $m } of { $n }
-            }
-    }
+item-count-m-of-n = { $m } of { $n }

 # Variables:
 #   $count - the number items
